import java.util.*;

class Solution {
    public boolean checkInclusion(String code, String message) {
        int m = code.length();
        if (m > message.length()) return false;
        int[] need = new int[26], have = new int[26];
        for (char c : code.toCharArray()) need[c - 'a']++;
        for (int i = 0; i < message.length(); i++) {
            have[message.charAt(i) - 'a']++;                   // letter entering
            if (i >= m) have[message.charAt(i - m) - 'a']--;   // letter leaving
            if (i >= m - 1 && Arrays.equals(have, need)) return true;
        }
        return false;
    }
}

