class Solution:
    def checkInclusion(self, code: str, message: str) -> bool:
        m = len(code); need = Counter(code); win = Counter()
        for i, c in enumerate(message):
            win[c] += 1
            if i >= m:
                d = message[i - m]; win[d] -= 1
                if win[d] == 0: del win[d]
            if win == need: return True
        return False

